const template_017 =
  ".ns-citation {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  /* Sit like a superscript but stay inside the line box: `super` pushes the\n     chip into the previous line's descenders and collides with tight prose.\n     A small em-relative raise + a real inline gap reads like Perplexity-style\n     citations without breaking line rhythm. */\n  vertical-align: 0.25em;\n  min-width: var(--ns-space-4);\n  height: var(--ns-space-4);\n  padding: 0 var(--ns-space-1);\n  margin-inline: var(--ns-space-1);\n  border: 1px solid var(--ns-primary-border);\n  border-radius: var(--ns-radius-sm);\n  background: var(--ns-primary-subtle);\n  color: var(--ns-primary);\n  font-family: var(--ns-font-mono);\n  font-size: var(--ns-text-3xs);\n  font-weight: 600;\n  line-height: 1;\n  cursor: pointer;\n  transition:\n    background-color var(--ns-ease-fast),\n    border-color var(--ns-ease-fast),\n    color var(--ns-ease-fast);\n}\n\n.ns-citation:hover {\n  background: color-mix(in srgb, var(--ns-primary) 16%, transparent);\n  border-color: var(--ns-primary);\n}\n\n.ns-citation:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: var(--ns-space-px);\n}\n\n.ns-citation.is-active {\n  background: var(--ns-primary);\n  border-color: var(--ns-primary);\n  color: var(--ns-primary-fg);\n}\n";
const template_018 =
  "/**\n * @component CitationChip\n * @layer 2\n * @depends theme-seed\n * @description Inline per-claim source marker [n] that pairs with a sources list —\n * the grounded-agent citation UX.\n */\n\nimport type { JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\n\ninterface CitationChipProps\n  extends Omit<JSX.HTMLAttributes<HTMLButtonElement>, 'class' | 'onClick'> {\n  /** 1-based citation number rendered in the chip. */\n  index: number;\n  /** Source label, surfaced as the hover title + accessible name. */\n  source?: string;\n  /** Active when its matching source row is selected. */\n  active?: boolean;\n  /** Invoked with the citation index on activation. */\n  onClick?: (index: number) => void;\n  class?: string;\n}\n\n/**\n * Renders a clickable superscript citation chip.\n */\nexport function CitationChip(\n  { index, source, active, onClick, class: className, ...props }: CitationChipProps,\n): VNode {\n  return (\n    <button\n      {...props}\n      type='button'\n      title={source}\n      aria-pressed={active ? 'true' : 'false'}\n      aria-label={source ? `Source ${index}: ${source}` : `Source ${index}`}\n      class={cn('ns-citation', active && 'is-active', className)}\n      onClick={() => onClick?.(index)}\n    >\n      {index}\n    </button>\n  );\n}\n";
