const template_056 =
  "/**\n * @module\n * @support markdown-pipeline\n * @layer 3\n * @depends citation-chip\n * @description Pure, dependency-free helpers behind the copy-based `markdown`\n * registry item: the `remarkCitations` mdast transform, the `stripIncompleteSyntax`\n * mid-stream guard, and `extendSanitizeSchema` — the whitelist that keeps the\n * MANDATORY `rehype-sanitize` pass safe while still allowing citation chips,\n * KaTeX math markup, and highlight.js class output.\n *\n * This module imports NO npm packages on purpose: it carries the load-bearing,\n * security-relevant logic so it can be type-checked, published, and unit-tested\n * inside `@netscript/fresh-ui` without pulling the unified/remark/rehype stack\n * into the package's own import graph. The `markdown.tsx` component wires these\n * helpers into a direct Preact processor; the npm dependencies live only on the\n * registry item and only land in the consuming app.\n */\n\n/** Custom element name emitted for a recognized citation token. */\nexport const CITATION_ELEMENT = 'citation-chip';\n\n/**\n * Citation token recognized in model output: a bracketed 1–3 digit index such\n * as `[1]`, matching the grounded-agent `[n]` convention shared with `message`.\n */\nexport const CITATION_PATTERN: RegExp = /\\[(\\d{1,3})\\]/g;\n\n/**\n * KaTeX (via `rehype-katex`) emits MathML/HTML elements that the default\n * sanitize schema would strip. These tag names are re-allowed so the sanitize\n * pass can run LAST without erasing rendered math.\n */\nexport const KATEX_TAG_NAMES: readonly string[] = [\n  'math',\n  'semantics',\n  'annotation',\n  'mrow',\n  'mi',\n  'mo',\n  'mn',\n  'ms',\n  'mtext',\n  'mspace',\n  'msup',\n  'msub',\n  'msubsup',\n  'mfrac',\n  'msqrt',\n  'mroot',\n  'munder',\n  'mover',\n  'munderover',\n  'mtable',\n  'mtr',\n  'mtd',\n  'mpadded',\n  'mphantom',\n  'menclose',\n  'mstyle',\n];\n\n/** Minimal mdast node shape touched by {@link remarkCitations}. */\nexport interface MdastNode {\n  /** Node type (e.g. `text`, `paragraph`, `root`, or a custom citation type). */\n  type: string;\n  /** Literal text value, present on `text` nodes. */\n  value?: string;\n  /** Child nodes, present on parent nodes. */\n  children?: MdastNode[];\n  /** hast hints used by `mdast-util-to-hast` to emit a custom element. */\n  data?: { hName?: string; hProperties?: Record<string, unknown> };\n}\n\n/** Minimal mdast root shape passed to the transformer. */\nexport interface MdastRoot extends MdastNode {\n  /** Root nodes are always of type `root`. */\n  type: 'root';\n  /** Top-level block children of the document. */\n  children: MdastNode[];\n}\n\n/** A unified transformer over an mdast tree. */\nexport type MdastTransformer = (tree: MdastRoot) => void;\n\n/**\n * Minimal `rehype-sanitize` schema shape. Kept structural so this module never\n * imports `rehype-sanitize`; the component passes the plugin's real\n * `defaultSchema` at call time.\n */\nexport interface SanitizeSchema {\n  /** Allowed tag names. */\n  tagNames?: string[] | null;\n  /** Allowed attributes, keyed by tag name (or `*` for all elements). */\n  attributes?: Record<string, unknown[]> | null;\n  /** Other schema fields passed through untouched (e.g. `protocols`, `clobber`). */\n  [key: string]: unknown;\n}\n\n/**\n * Splits a text node on citation tokens, replacing each `[n]` with a node that\n * renders as a `<citation-chip index=\"n\">` element (via `data.hName`).\n * @param node - The mdast `text` node to scan.\n * @returns The original node, or the split sequence of text + citation nodes.\n */\nfunction splitTextNode(node: MdastNode): MdastNode[] {\n  const value = node.value ?? '';\n  CITATION_PATTERN.lastIndex = 0;\n  if (!CITATION_PATTERN.test(value)) return [node];\n\n  CITATION_PATTERN.lastIndex = 0;\n  const out: MdastNode[] = [];\n  let last = 0;\n  let match: RegExpExecArray | null;\n  while ((match = CITATION_PATTERN.exec(value)) !== null) {\n    if (match.index > last) {\n      out.push({ type: 'text', value: value.slice(last, match.index) });\n    }\n    const index = Number(match[1]);\n    out.push({\n      type: 'citationReference',\n      data: { hName: CITATION_ELEMENT, hProperties: { index } },\n      children: [{ type: 'text', value: match[1] }],\n    });\n    last = match.index + match[0].length;\n  }\n  if (last < value.length) out.push({ type: 'text', value: value.slice(last) });\n  return out;\n}\n\n/**\n * Recursively rewrites citation tokens within a node's children.\n * @param node - The parent node whose children are scanned.\n */\nfunction visit(node: MdastNode): void {\n  if (!node.children) return;\n  const next: MdastNode[] = [];\n  for (const child of node.children) {\n    if (child.type === 'text') {\n      next.push(...splitTextNode(child));\n    } else {\n      visit(child);\n      next.push(child);\n    }\n  }\n  node.children = next;\n}\n\n/**\n * A remark plugin that rewrites `[n]` citation tokens in model output into\n * `citation-chip` render calls. Pair with `components={{ 'citation-chip': ... }}`\n * on `rehype-react` to render the sibling `citation-chip` registry item.\n * @returns The mdast transformer.\n * @example\n * ```ts\n * import { remarkCitations } from './markdown-pipeline.ts';\n * const transform = remarkCitations();\n * transform({ type: 'root', children: [] });\n * ```\n */\nexport function remarkCitations(): MdastTransformer {\n  return (tree: MdastRoot): void => {\n    visit(tree);\n  };\n}\n\n/**\n * Counts non-overlapping occurrences of a marker in text.\n * @param text - The text to scan.\n * @param marker - The literal marker to count.\n * @returns The occurrence count.\n */\nfunction countMarker(text: string, marker: string): number {\n  let count = 0;\n  let index = text.indexOf(marker);\n  while (index !== -1) {\n    count += 1;\n    index = text.indexOf(marker, index + marker.length);\n  }\n  return count;\n}\n\n/**\n * Pre-processes a possibly-truncated mid-stream markdown chunk so partial GFM /\n * math syntax renders meaningfully instead of leaking raw markers. Unterminated\n * fenced code blocks, inline code spans, bold runs, and math are closed, and a\n * dangling incomplete link/image at the tail is dropped. Complete input is\n * returned effectively unchanged.\n * @param chunk - The (possibly partial) markdown source.\n * @returns The repaired markdown source, safe to feed to the renderer.\n * @example\n * ```ts\n * stripIncompleteSyntax('Here is **bold'); // -> 'Here is **bold**'\n * ```\n */\nexport function stripIncompleteSyntax(chunk: string): string {\n  let text = chunk;\n\n  // 1) Close an unterminated fenced code block (odd number of ``` fences).\n  if (countMarker(text, '```') % 2 === 1) {\n    if (!text.endsWith('\\n')) text += '\\n';\n    text += '```';\n  }\n\n  // Mask now-balanced fenced blocks so inline scanning ignores code content.\n  const masked = text.replace(/```[\\s\\S]*?```/g, '');\n\n  // 2) Close an unterminated inline code span.\n  if (countMarker(masked, '`') % 2 === 1) text += '`';\n\n  // 3) Close an unterminated bold/strong run.\n  if (countMarker(masked, '**') % 2 === 1) text += '**';\n\n  // 4) Close unterminated block math, else unterminated inline math.\n  if (countMarker(masked, '$$') % 2 === 1) {\n    text += '$$';\n  } else if (countMarker(masked.replace(/\\$\\$/g, ''), '$') % 2 === 1) {\n    text += '$';\n  }\n\n  // 5) Drop a dangling incomplete link/image at the very end.\n  text = text\n    .replace(/!?\\[[^\\]]*\\]\\([^)]*$/, '')\n    .replace(/!?\\[[^\\]]*$/, '');\n\n  return text;\n}\n\n/** Minimal hast node shape touched by {@link rehypeInlineStyles}. */\nexport interface HastNode {\n  /** Node type (e.g. `element`, `text`, `root`). */\n  type: string;\n  /** Element tag name, present on `element` nodes. */\n  tagName?: string;\n  /** Element properties, present on `element` nodes. */\n  properties?: Record<string, unknown>;\n  /** Child nodes, present on parent nodes. */\n  children?: HastNode[];\n}\n\n/** A unified transformer over a hast tree. */\nexport type HastTransformer = (tree: HastNode) => void;\n\n/**\n * Parses an inline `style` attribute string into a camelCased declaration\n * object (`react`/Preact style-prop shape). Custom properties (`--x`) keep\n * their literal name. Malformed declarations are skipped, never thrown.\n * @param style - The raw inline CSS declaration list.\n * @returns The camelCased property/value map.\n * @example\n * ```ts\n * parseStyleDeclarations('height:0.81em;margin-left:-0.05em');\n * // -> { height: '0.81em', marginLeft: '-0.05em' }\n * ```\n */\nexport function parseStyleDeclarations(style: string): Record<string, string> {\n  const out: Record<string, string> = {};\n  for (const declaration of style.split(';')) {\n    const colon = declaration.indexOf(':');\n    if (colon === -1) continue;\n    const property = declaration.slice(0, colon).trim();\n    const value = declaration.slice(colon + 1).trim();\n    if (!property || !value) continue;\n    const key = property.startsWith('--')\n      ? property\n      : property.replace(/-+([a-z])/g, (_, ch: string) => ch.toUpperCase());\n    out[key] = value;\n  }\n  return out;\n}\n\n/**\n * A rehype plugin that replaces string `style` properties with parsed style\n * OBJECTS before the Preact JSX compiler. This keeps KaTeX vertical layout\n * (struts/vlists) bundler-independent while avoiding any renderer-specific\n * string-style parser. Object values are passed through untouched by the\n * runtime. Run this AFTER `rehype-sanitize` (sanitize expects string values).\n * @returns The hast transformer.\n * @example\n * ```ts\n * const transform = rehypeInlineStyles();\n * transform({ type: 'root', children: [] });\n * ```\n */\nexport function rehypeInlineStyles(): HastTransformer {\n  const walk = (node: HastNode): void => {\n    if (node.properties && typeof node.properties.style === 'string') {\n      node.properties.style = parseStyleDeclarations(node.properties.style);\n    }\n    if (node.children) { for (const child of node.children) walk(child); }\n  };\n  return walk;\n}\n\n/**\n * Extends a base `rehype-sanitize` schema so the MANDATORY final sanitize pass\n * keeps citation chips, KaTeX math markup, and highlight.js class output while\n * still stripping anything dangerous. `script` is force-removed from the allowed\n * tag set and no event-handler attribute is ever added, so model-authored\n * `<script>` / `on*=` HTML can never survive the pass.\n * @param base - The plugin's `defaultSchema` (passed structurally).\n * @returns A new schema; the input is not mutated.\n * @example\n * ```ts\n * import { defaultSchema } from 'rehype-sanitize';\n * const schema = extendSanitizeSchema(defaultSchema);\n * ```\n */\nexport function extendSanitizeSchema(base: SanitizeSchema): SanitizeSchema {\n  const tagNames = new Set<string>(base.tagNames ?? []);\n  // Sanitize is non-negotiable: scripts never render, no matter the base schema.\n  tagNames.delete('script');\n  tagNames.add(CITATION_ELEMENT);\n  for (const tag of KATEX_TAG_NAMES) tagNames.add(tag);\n\n  const attributes: Record<string, unknown[]> = { ...(base.attributes ?? {}) };\n  attributes['*'] = [...new Set<unknown>([...(attributes['*'] ?? []), 'className', 'class'])];\n  attributes['span'] = [\n    ...new Set<unknown>([\n      ...(attributes['span'] ?? []),\n      'className',\n      'class',\n      'style',\n      // hast property name is camelCase; keep the attribute form too so the\n      // schema works regardless of how the tree was produced.\n      'ariaHidden',\n      'aria-hidden',\n    ]),\n  ];\n  attributes['div'] = [\n    ...new Set<unknown>([...(attributes['div'] ?? []), 'className', 'class', 'style']),\n  ];\n  attributes[CITATION_ELEMENT] = ['index', 'source', 'className', 'class'];\n\n  return { ...base, tagNames: [...tagNames], attributes };\n}\n";
const template_057 =
  '.ns-markdown {\n  color: var(--ns-fg);\n  font-family: var(--ns-font-sans);\n  font-size: var(--ns-text-sm);\n  line-height: 1.65;\n  overflow-wrap: anywhere;\n}\n\n.ns-markdown > :first-child {\n  margin-top: 0;\n}\n\n.ns-markdown > :last-child {\n  margin-bottom: 0;\n}\n\n.ns-markdown p,\n.ns-markdown ul,\n.ns-markdown ol,\n.ns-markdown blockquote,\n.ns-markdown pre,\n.ns-markdown table {\n  margin-block: var(--ns-space-3);\n}\n\n.ns-markdown h1,\n.ns-markdown h2,\n.ns-markdown h3,\n.ns-markdown h4 {\n  margin-block: var(--ns-space-4) var(--ns-space-2);\n  font-weight: 600;\n  line-height: 1.3;\n}\n\n.ns-markdown h1 {\n  font-size: var(--ns-text-lg);\n}\n\n.ns-markdown h2,\n.ns-markdown h3,\n.ns-markdown h4 {\n  font-size: var(--ns-text-sm);\n}\n\n.ns-markdown a {\n  color: var(--ns-primary);\n  text-decoration: underline;\n  text-underline-offset: 2px;\n}\n\n.ns-markdown a:hover {\n  color: color-mix(in srgb, var(--ns-primary) 80%, var(--ns-fg));\n}\n\n/* Own the list markers: host resets (Tailwind preflight, Fresh scaffolds)\n   zero out list-style, which silently drops bullets from rendered prose. */\n.ns-markdown ul,\n.ns-markdown ol {\n  list-style-position: outside;\n  padding-inline-start: var(--ns-space-5);\n}\n\n.ns-markdown ul {\n  list-style-type: disc;\n}\n\n.ns-markdown ol {\n  list-style-type: decimal;\n}\n\n.ns-markdown li::marker {\n  color: var(--ns-muted-fg);\n}\n\n.ns-markdown li {\n  margin-block: var(--ns-space-1);\n}\n\n.ns-markdown blockquote {\n  padding-inline-start: var(--ns-space-3);\n  border-inline-start: 2px solid var(--ns-primary-border);\n  color: var(--ns-muted-fg);\n}\n\n.ns-markdown code {\n  font-family: var(--ns-font-mono);\n  font-size: 0.85em;\n}\n\n.ns-markdown :not(pre) > code {\n  padding: var(--ns-space-px) var(--ns-space-1);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-sm);\n  background: color-mix(in srgb, var(--ns-muted-fg) 12%, transparent);\n}\n\n.ns-markdown pre {\n  padding: var(--ns-space-3);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-md);\n  background: var(--ns-surface);\n  overflow-x: auto;\n}\n\n.ns-markdown pre code {\n  padding: 0;\n  border: 0;\n  background: transparent;\n}\n\n.ns-markdown table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--ns-text-xs);\n}\n\n.ns-markdown th,\n.ns-markdown td {\n  padding: var(--ns-space-2) var(--ns-space-3);\n  border: 1px solid var(--ns-border);\n  text-align: start;\n}\n\n.ns-markdown th {\n  background: color-mix(in srgb, var(--ns-muted-fg) 8%, transparent);\n  font-weight: 600;\n}\n\n.ns-markdown hr {\n  margin-block: var(--ns-space-4);\n  border: 0;\n  border-top: 1px solid var(--ns-border);\n}\n\n.ns-markdown .katex-display {\n  margin-block: var(--ns-space-3);\n  overflow-x: auto;\n  overflow-y: hidden;\n}\n\n/* Syntax highlighting palette for rehype-highlight output. Registry-owned and\n   token-driven so code colors follow the active theme — a stock highlight.js\n   stylesheet is theme-fixed and breaks contrast on the opposite theme. */\n.ns-markdown .hljs-comment,\n.ns-markdown .hljs-quote,\n.ns-markdown .hljs-meta {\n  color: var(--ns-muted-fg);\n  font-style: italic;\n}\n\n.ns-markdown .hljs-keyword,\n.ns-markdown .hljs-selector-tag,\n.ns-markdown .hljs-doctag,\n.ns-markdown .hljs-tag,\n.ns-markdown .hljs-name {\n  color: var(--ns-primary);\n}\n\n.ns-markdown .hljs-string,\n.ns-markdown .hljs-regexp,\n.ns-markdown .hljs-addition {\n  color: var(--ns-success);\n}\n\n.ns-markdown .hljs-number,\n.ns-markdown .hljs-literal,\n.ns-markdown .hljs-symbol,\n.ns-markdown .hljs-bullet,\n.ns-markdown .hljs-link {\n  color: var(--ns-warning);\n}\n\n.ns-markdown .hljs-title,\n.ns-markdown .hljs-section,\n.ns-markdown .hljs-attr,\n.ns-markdown .hljs-attribute,\n.ns-markdown .hljs-selector-id,\n.ns-markdown .hljs-selector-class,\n.ns-markdown .hljs-template-variable,\n.ns-markdown .hljs-variable {\n  color: var(--ns-secondary);\n}\n\n.ns-markdown .hljs-built_in,\n.ns-markdown .hljs-type,\n.ns-markdown .hljs-class {\n  color: color-mix(in srgb, var(--ns-secondary) 60%, var(--ns-fg));\n}\n\n.ns-markdown .hljs-deletion {\n  color: var(--ns-destructive);\n}\n\n.ns-markdown .hljs-emphasis {\n  font-style: italic;\n}\n\n.ns-markdown .hljs-strong {\n  font-weight: 600;\n}\n';
const template_058 =
  "/**\n * @component Markdown\n * @layer 3\n * @depends theme-seed, citation-chip\n * @description Sanitized GFM + math + syntax-highlighted renderer for streamed\n * assistant / chat output. Uses a unified pipeline with `remark-gfm` +\n * `remark-math` + the local `remarkCitations` transform, then `rehype-katex` +\n * `rehype-highlight`, a MANDATORY `rehype-sanitize` pass, and `rehype-react`\n * configured with the Preact JSX runtime. `stripIncompleteSyntax` guards a\n * truncated mid-stream chunk so partial syntax never renders as raw markers.\n *\n * Copy-based item — the npm dependencies (`unified`, `remark-*`, `rehype-*`,\n * `katex`, `highlight.js`) are declared on the registry item and are merged into\n * the CONSUMING app's `deno.json`, never into `@netscript/fresh-ui`.\n *\n * App wiring: the final hast tree compiles directly through `preact/jsx-runtime`;\n * no React compatibility alias is required. KaTeX styles are imported by the\n * styles aggregator this item contributes.\n */\n\nimport { Fragment, type VNode } from 'preact';\nimport { jsx, jsxs } from 'preact/jsx-runtime';\nimport rehypeReact from 'rehype-react';\nimport remarkGfm from 'remark-gfm';\nimport remarkMath from 'remark-math';\nimport remarkParse from 'remark-parse';\nimport remarkRehype from 'remark-rehype';\nimport rehypeKatex from 'rehype-katex';\nimport rehypeHighlight from 'rehype-highlight';\nimport rehypeSanitize, { defaultSchema } from 'rehype-sanitize';\nimport { unified } from 'unified';\nimport { CitationChip } from './citation-chip.tsx';\nimport {\n  extendSanitizeSchema,\n  rehypeInlineStyles,\n  remarkCitations,\n  stripIncompleteSyntax,\n} from './markdown-pipeline.ts';\n\n/** Sanitize schema is built once: citation chips + KaTeX + hljs allowed, scripts never. */\nconst SANITIZE_SCHEMA = extendSanitizeSchema(defaultSchema);\n\n/** Properties emitted by the citation mdast transform. */\ninterface CitationElementProps {\n  index?: string | number;\n  source?: string;\n}\n\n/** Per-render state captured by the citation component mapping. */\ninterface MarkdownProcessorOptions {\n  activeCite?: number;\n  onCite?: (index: number) => void;\n}\n\n/**\n * Creates the direct unified-to-Preact processor for one Markdown render.\n * Pipeline order is load-bearing: sanitize is the final content transform and\n * is never caller-configurable. `rehypeInlineStyles` only reshapes already-safe\n * style strings before the Preact compiler, preserving KaTeX layout.\n */\nfunction createMarkdownProcessor({ activeCite, onCite }: MarkdownProcessorOptions) {\n  const components = {\n    'citation-chip': (props: CitationElementProps): VNode => {\n      const index = Number(props.index);\n      return (\n        <CitationChip\n          index={index}\n          source={props.source}\n          active={activeCite === index}\n          onClick={onCite}\n        />\n      );\n    },\n  };\n\n  return unified()\n    .use(remarkParse)\n    .use(remarkGfm)\n    .use(remarkMath)\n    .use(remarkCitations)\n    .use(remarkRehype)\n    .use(rehypeKatex)\n    .use(rehypeHighlight)\n    .use(rehypeSanitize, SANITIZE_SCHEMA)\n    .use(rehypeInlineStyles)\n    .use(rehypeReact, {\n      Fragment,\n      jsx,\n      jsxs,\n      elementAttributeNameCase: 'html',\n      stylePropertyNameCase: 'dom',\n      components,\n    });\n}\n\n/** Props for the {@link Markdown} renderer. */\nexport interface MarkdownProps {\n  /** Raw model / assistant markdown source. */\n  children: string;\n  /** Pre-process a possibly-truncated mid-stream chunk before rendering. */\n  streaming?: boolean;\n  /** Invoked with the citation index when a rendered chip is activated. */\n  onCite?: (index: number) => void;\n  /** Currently active citation index (highlights its chip). */\n  activeCite?: number;\n  /** Extra class names for the wrapper. */\n  class?: string;\n}\n\n/**\n * Renders sanitized markdown from streamed assistant output.\n * @param props - {@link MarkdownProps}.\n * @returns The rendered prose surface.\n */\nexport function Markdown(\n  { children, streaming = false, onCite, activeCite, class: className }: MarkdownProps,\n): VNode {\n  const source = streaming ? stripIncompleteSyntax(children) : children;\n  const content = createMarkdownProcessor({ activeCite, onCite }).processSync(source).result;\n\n  return (\n    <div class={className ? `ns-markdown ${className}` : 'ns-markdown'}>\n      {content}\n    </div>\n  );\n}\n";
const template_059 =
  '.ns-message {\n  display: flex;\n  align-items: flex-start;\n  gap: var(--ns-space-2-5);\n}\n\n.ns-message__avatar {\n  flex-shrink: 0;\n  padding-top: var(--ns-space-0-5);\n}\n\n.ns-message__main {\n  display: flex;\n  flex-direction: column;\n  gap: var(--ns-space-1-5);\n  min-width: 0;\n  flex: 1;\n}\n\n.ns-message__head {\n  display: flex;\n  align-items: baseline;\n  gap: var(--ns-space-2);\n}\n\n.ns-message__author {\n  font-size: var(--ns-text-sm);\n  font-weight: 600;\n  color: var(--ns-fg);\n}\n\n.ns-message__model {\n  font-family: var(--ns-font-mono);\n  font-size: var(--ns-text-2xs);\n  color: var(--ns-muted-fg);\n}\n\n.ns-message__time {\n  margin-inline-start: auto;\n  font-size: var(--ns-text-2xs);\n  color: var(--ns-muted-fg);\n}\n\n.ns-message__body {\n  display: flex;\n  flex-direction: column;\n  gap: var(--ns-space-3);\n  font-size: var(--ns-text-chat);\n  line-height: var(--ns-leading-relaxed);\n  color: var(--ns-fg);\n}\n\n.ns-message__text {\n  margin: 0;\n}\n\n.ns-inline-code {\n  padding: 0 var(--ns-space-1);\n  border-radius: var(--ns-radius-sm);\n  background: var(--ns-muted);\n  color: var(--ns-fg);\n  font-family: var(--ns-font-mono);\n  font-size: 0.9em;\n}\n\n.ns-message__actions {\n  display: flex;\n  gap: var(--ns-space-1);\n  opacity: 0;\n  transition: opacity var(--ns-ease-fast);\n}\n\n.ns-message:hover .ns-message__actions,\n.ns-message:focus-within .ns-message__actions {\n  opacity: 1;\n}\n\n.ns-msg-action {\n  padding: var(--ns-space-0-5) var(--ns-space-1-5);\n  border: 0;\n  border-radius: var(--ns-radius-sm);\n  background: transparent;\n  color: var(--ns-muted-fg);\n  font-size: var(--ns-text-2xs);\n  cursor: pointer;\n}\n\n.ns-msg-action:hover {\n  color: var(--ns-fg);\n  background: var(--ns-muted);\n}\n\n.ns-msg-action:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: -1px;\n}\n\n/* User — right-aligned solid primary bubble (iMessage idiom, matches prototype) */\n.ns-message--user {\n  flex-direction: row-reverse;\n  margin-inline-start: auto;\n  max-width: min(82%, 640px);\n}\n\n.ns-message--user .ns-message__main {\n  align-items: flex-end;\n}\n\n.ns-message--user .ns-message__head {\n  flex-direction: row-reverse;\n}\n\n.ns-message--user .ns-message__time {\n  margin-inline-start: 0;\n}\n\n.ns-message--user .ns-message__body {\n  align-items: flex-end;\n  padding: var(--ns-space-3) var(--ns-space-4);\n  border-radius: var(--ns-radius-xl) var(--ns-radius-xl) var(--ns-radius-sm) var(--ns-radius-xl);\n  background: var(--ns-primary);\n  color: var(--ns-primary-fg);\n}\n\n/* System — centered muted note */\n.ns-message--system {\n  justify-content: center;\n}\n\n.ns-message--system .ns-message__avatar {\n  display: none;\n}\n\n.ns-message--system .ns-message__body {\n  text-align: center;\n  font-size: var(--ns-text-xs);\n  color: var(--ns-muted-fg);\n}\n\n/* Follow-up chips reuse the shared pill seam (mirrors prompt-input). */\n.ns-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ns-space-1);\n  height: var(--ns-control-h-sm);\n  padding-inline: var(--ns-space-2-5);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-full);\n  background: transparent;\n  color: var(--ns-muted-fg);\n  font-size: var(--ns-text-2xs);\n  cursor: pointer;\n  transition:\n    color var(--ns-ease-fast),\n    border-color var(--ns-ease-fast),\n    background-color var(--ns-ease-fast);\n}\n\n.ns-pill:hover {\n  color: var(--ns-fg);\n  border-color: var(--ns-border-hover);\n}\n\n.ns-pill:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: var(--ns-space-px);\n}\n\n/* Typing indicator */\n.ns-typing {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ns-space-1);\n  padding: var(--ns-space-1) 0;\n}\n\n.ns-typing > span {\n  width: var(--ns-space-1-5);\n  height: var(--ns-space-1-5);\n  border-radius: var(--ns-radius-full);\n  background: var(--ns-muted-fg);\n  animation: ns-typing-bounce 1.2s infinite ease-in-out;\n}\n\n.ns-typing > span:nth-child(2) {\n  animation-delay: 0.15s;\n}\n\n.ns-typing > span:nth-child(3) {\n  animation-delay: 0.3s;\n}\n\n@keyframes ns-typing-bounce {\n  0%,\n  60%,\n  100% {\n    /* Resting dots must stay clearly visible on both themes; 0.3 reads as\n       almost-invisible against subtle surfaces. */\n    opacity: 0.55;\n    transform: translateY(0);\n  }\n  30% {\n    opacity: 1;\n    transform: translateY(calc(-1 * var(--ns-space-1)));\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ns-message__actions,\n  .ns-pill {\n    transition: none;\n  }\n\n  .ns-typing > span {\n    animation: none;\n    opacity: 0.6;\n  }\n}\n';
const template_060 =
  "/**\n * @component Message\n * @layer 2\n * @depends theme-seed\n * @description A chat message in a thread: author + time, inline-markup body\n * (**bold**, `code`, [n] citations), tool-call + chart/code blocks, follow-up\n * chips, and hover actions. User messages are right-aligned bubbles; assistant\n * messages are card-less prose. Exports `renderInline` and `TypingIndicator`.\n */\n\nimport type { JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\nimport { Avatar } from './avatar.tsx';\nimport { CitationChip } from './citation-chip.tsx';\nimport { ChartBlock, type ChartDatum } from './chart-block.tsx';\nimport { CodeBlock } from './code-block.tsx';\nimport { ToolCallCard, type ToolCallStatus } from './tool-call-card.tsx';\n\nexport type MessageRole = 'user' | 'assistant' | 'system';\n\nexport interface MessageAuthor {\n  name: string;\n  initials?: string;\n  agent?: boolean;\n}\n\nexport type MessageBlock =\n  | {\n    type: 'chart';\n    title?: string;\n    sub?: string;\n    data: ChartDatum[];\n    unit?: string;\n    variant?: 'bar' | 'column';\n  }\n  | { type: 'code'; code: string; filename?: string; lang?: string };\n\nexport interface MessageTool {\n  name: string;\n  args?: string;\n  result?: string;\n  status: ToolCallStatus;\n  defaultOpen?: boolean;\n}\n\nexport interface MessageData {\n  role: MessageRole;\n  author: MessageAuthor;\n  time?: string;\n  model?: string;\n  body?: string;\n  blocks?: MessageBlock[];\n  tools?: MessageTool[];\n  followups?: string[];\n  /** Show the typing indicator instead of a body (assistant in-progress). */\n  pending?: boolean;\n}\n\n/**\n * Wiring for citations + follow-ups shared with the surrounding thread.\n */\nexport interface MessageCtx {\n  activeCite?: number;\n  onCite?: (index: number) => void;\n  onFollowup?: (text: string) => void;\n}\n\nconst INLINE = /(\\*\\*([^*]+)\\*\\*)|(`([^`]+)`)|(\\[(\\d+)\\])/g;\n\n/**\n * Turns a string with `**bold**`, `` `code` ``, and `[n]` citation markers into\n * an array of text + element nodes. Exported for reuse in other prose surfaces.\n */\nexport function renderInline(text: string, ctx?: MessageCtx): (string | VNode)[] {\n  const nodes: (string | VNode)[] = [];\n  let last = 0;\n  let match: RegExpExecArray | null;\n  INLINE.lastIndex = 0;\n  while ((match = INLINE.exec(text)) !== null) {\n    if (match.index > last) nodes.push(text.slice(last, match.index));\n    if (match[2] !== undefined) {\n      nodes.push(<strong>{match[2]}</strong>);\n    } else if (match[4] !== undefined) {\n      nodes.push(<code class='ns-inline-code'>{match[4]}</code>);\n    } else if (match[6] !== undefined) {\n      const index = Number(match[6]);\n      nodes.push(\n        <CitationChip index={index} active={ctx?.activeCite === index} onClick={ctx?.onCite} />,\n      );\n    }\n    last = INLINE.lastIndex;\n  }\n  if (last < text.length) nodes.push(text.slice(last));\n  return nodes;\n}\n\n/**\n * Animated \"assistant is typing\" indicator.\n */\nexport function TypingIndicator(): VNode {\n  return (\n    <span class='ns-typing' role='status' aria-label='Assistant is typing'>\n      <span></span>\n      <span></span>\n      <span></span>\n    </span>\n  );\n}\n\nfunction renderBlock(block: MessageBlock): VNode {\n  if (block.type === 'chart') {\n    return (\n      <ChartBlock\n        title={block.title}\n        sub={block.sub}\n        data={block.data}\n        unit={block.unit}\n        variant={block.variant}\n      />\n    );\n  }\n  return <CodeBlock code={block.code} filename={block.filename} lang={block.lang} />;\n}\n\ninterface MessageProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'class'> {\n  message: MessageData;\n  ctx?: MessageCtx;\n  class?: string;\n}\n\n/**\n * Renders a single chat message.\n */\nexport function Message({ message, ctx, class: className, ...props }: MessageProps): VNode {\n  const { role, author, time, model, body, blocks, tools, followups, pending } = message;\n\n  return (\n    <div {...props} class={cn('ns-message', `ns-message--${role}`, className)}>\n      <div class='ns-message__avatar'>\n        <Avatar name={author.name} initials={author.initials} agent={author.agent} size='sm' />\n      </div>\n      <div class='ns-message__main'>\n        <div class='ns-message__head'>\n          <span class='ns-message__author'>{author.name}</span>\n          {model ? <span class='ns-message__model'>{model}</span> : null}\n          {time ? <span class='ns-message__time'>{time}</span> : null}\n        </div>\n        <div class='ns-message__body'>\n          {pending ? <TypingIndicator /> : null}\n          {body ? <p class='ns-message__text'>{renderInline(body, ctx)}</p> : null}\n          {blocks?.map((block, index) => <div key={`b${index}`}>{renderBlock(block)}</div>)}\n          {tools?.map((tool, index) => (\n            <ToolCallCard\n              key={`t${index}`}\n              name={tool.name}\n              args={tool.args}\n              result={tool.result}\n              status={tool.status}\n              defaultOpen={tool.defaultOpen}\n            />\n          ))}\n        </div>\n        {followups && followups.length\n          ? (\n            <div class='ns-message__followups ns-cluster ns-cluster--sm'>\n              {followups.map((followup, index) => (\n                <button\n                  key={`f${index}`}\n                  type='button'\n                  class='ns-pill'\n                  onClick={() => ctx?.onFollowup?.(followup)}\n                >\n                  {followup}\n                </button>\n              ))}\n            </div>\n          )\n          : null}\n        <div class='ns-message__actions'>\n          <button type='button' class='ns-msg-action' aria-label='Copy message'>Copy</button>\n          <button type='button' class='ns-msg-action' aria-label='Regenerate response'>\n            Regenerate\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n";
const template_061 =
  ".ns-model-selector {\n  position: relative;\n  display: inline-block;\n}\n\n.ns-model-selector__btn {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ns-space-1-5);\n  height: var(--ns-control-h-sm);\n  padding-inline: var(--ns-space-2-5);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-md);\n  background: var(--ns-surface);\n  color: var(--ns-fg);\n  font-size: var(--ns-text-xs);\n  cursor: pointer;\n  user-select: none;\n  list-style: none;\n}\n\n.ns-model-selector__btn::-webkit-details-marker {\n  display: none;\n}\n\n.ns-model-selector__btn:hover {\n  border-color: var(--ns-border-hover);\n}\n\n.ns-model-selector__btn:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: var(--ns-space-px);\n}\n\n.ns-model-selector__provider {\n  font-family: var(--ns-font-mono);\n  font-size: var(--ns-text-2xs);\n  color: var(--ns-muted-fg);\n}\n\n.ns-model-selector__menu {\n  position: absolute;\n  top: calc(100% + var(--ns-space-1));\n  left: 0;\n  z-index: var(--ns-z-dropdown);\n  display: flex;\n  flex-direction: column;\n  gap: var(--ns-space-px);\n  min-width: 14rem;\n  padding: var(--ns-space-1);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-md);\n  background: var(--ns-surface-raised);\n  box-shadow: var(--ns-shadow-lg);\n}\n\n.ns-model-selector[data-align='right'] .ns-model-selector__menu {\n  left: auto;\n  right: 0;\n}\n\n.ns-model-opt {\n  display: flex;\n  align-items: center;\n  gap: var(--ns-space-2);\n  width: 100%;\n  padding: var(--ns-space-1-5) var(--ns-space-2);\n  border: 0;\n  border-radius: var(--ns-radius-sm);\n  background: transparent;\n  color: var(--ns-fg);\n  text-align: start;\n  cursor: pointer;\n}\n\n.ns-model-opt:hover {\n  background: var(--ns-muted);\n}\n\n.ns-model-opt:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: -2px;\n}\n\n.ns-model-opt__main {\n  display: flex;\n  flex-direction: column;\n  gap: var(--ns-space-0-5);\n  min-width: 0;\n  flex: 1;\n}\n\n.ns-model-opt__label {\n  font-size: var(--ns-text-sm);\n  font-weight: 500;\n}\n\n.ns-model-opt__desc {\n  font-size: var(--ns-text-2xs);\n  color: var(--ns-muted-fg);\n}\n\n.ns-model-opt__check {\n  color: var(--ns-primary);\n  font-size: var(--ns-text-sm);\n}\n\n.ns-model-opt.is-active .ns-model-opt__label {\n  color: var(--ns-primary);\n}\n";
const template_062 =
  "/**\n * @component ModelSelector\n * @layer 2\n * @depends theme-seed\n * @description Model/provider picker for the prompt composer. Native-first: a\n * <details> disclosure holds the option list (open/close + Esc are native;\n * an app island may add outside-click-close and auto-close on select).\n */\n\nimport type { JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\n\n/**\n * A selectable model entry.\n */\nexport interface ModelOption {\n  id: string;\n  label: string;\n  provider?: string;\n  desc?: string;\n}\n\ninterface ModelSelectorProps\n  extends Omit<JSX.HTMLAttributes<HTMLDetailsElement>, 'class' | 'onChange'> {\n  /** Selected model id. */\n  value: string;\n  /** Available models. */\n  models: ModelOption[];\n  /** Invoked with the chosen model id. */\n  onChange?: (id: string) => void;\n  /** Menu alignment relative to the trigger. */\n  align?: 'left' | 'right';\n  class?: string;\n}\n\n/**\n * Renders a disclosure-backed model picker.\n */\nexport function ModelSelector(\n  { value, models, onChange, align = 'left', class: className, ...props }: ModelSelectorProps,\n): VNode {\n  const current = models.find((model) => model.id === value) ?? models[0];\n\n  return (\n    <details {...props} class={cn('ns-model-selector', className)} data-align={align}>\n      <summary class='ns-model-selector__btn'>\n        {current?.provider\n          ? <span class='ns-model-selector__provider'>{current.provider}</span>\n          : null}\n        <span>{current?.label}</span>\n      </summary>\n      <div class='ns-model-selector__menu' role='listbox'>\n        {models.map((model) => {\n          const selected = model.id === value;\n          return (\n            <button\n              key={model.id}\n              type='button'\n              role='option'\n              aria-selected={selected ? 'true' : 'false'}\n              class={cn('ns-model-opt', selected && 'is-active')}\n              onClick={() => onChange?.(model.id)}\n            >\n              <span class='ns-model-opt__main'>\n                <span class='ns-model-opt__label'>{model.label}</span>\n                {model.desc ? <span class='ns-model-opt__desc'>{model.desc}</span> : null}\n              </span>\n              {selected ? <span class='ns-model-opt__check' aria-hidden='true'>✓</span> : null}\n            </button>\n          );\n        })}\n      </div>\n    </details>\n  );\n}\n";
