  '.ns-panel {\n  background: color-mix(in srgb, var(--ns-surface) 92%, var(--ns-card));\n  color: var(--ns-fg);\n}\n\n.ns-panel--muted {\n  background: color-mix(in srgb, var(--ns-muted) 14%, var(--ns-surface));\n}\n\n.ns-panel--raised {\n  background: var(--ns-surface-raised);\n  box-shadow: var(--ns-shadow-xs);\n}\n\n.ns-panel__header {\n  padding: var(--ns-space-4) var(--ns-space-5);\n  border-bottom: 1px solid var(--ns-border);\n}\n\n.ns-panel__body {\n  padding: var(--ns-space-4) var(--ns-space-5);\n}\n\n.ns-panel__footer {\n  padding: var(--ns-space-3) var(--ns-space-5);\n  border-top: 1px solid var(--ns-border);\n  background: color-mix(in srgb, var(--ns-surface) 86%, transparent);\n}\n';
const template_068 =
  "/**\n * @component Panel\n * @layer 2\n * @depends theme-seed\n * @description Dense secondary surface for sidebars, filter rails, and grouped dashboard controls.\n */\n\nimport type { ComponentChildren, JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\n\nexport type PanelTone = 'default' | 'muted' | 'raised';\n\nexport interface PanelProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'class' | 'children'> {\n  children: ComponentChildren;\n  class?: string;\n  tone?: PanelTone;\n}\n\ninterface PanelSectionProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'class' | 'children'> {\n  children: ComponentChildren;\n  class?: string;\n}\n\ninterface PanelTextProps\n  extends Omit<JSX.HTMLAttributes<HTMLParagraphElement>, 'class' | 'children'> {\n  children: ComponentChildren;\n  class?: string;\n}\n\nconst TONE_CLASSES: Record<PanelTone, string | undefined> = {\n  default: undefined,\n  muted: 'ns-panel--muted',\n  raised: 'ns-panel--raised',\n};\n\nfunction PanelRoot({ children, class: className, tone = 'default', ...props }: PanelProps): VNode {\n  return <div {...props} class={cn('ns-panel', TONE_CLASSES[tone], className)}>{children}</div>;\n}\n\nexport function PanelHeader({ children, class: className, ...props }: PanelSectionProps): VNode {\n  return <div {...props} class={cn('ns-panel__header', className)}>{children}</div>;\n}\n\nexport function PanelTitle({ children, class: className, ...props }: PanelTextProps): VNode {\n  return <p {...props} class={cn('ns-panel__title', className)}>{children}</p>;\n}\n\nexport function PanelDescription({ children, class: className, ...props }: PanelTextProps): VNode {\n  return <p {...props} class={cn('ns-panel__description', className)}>{children}</p>;\n}\n\nexport function PanelBody({ children, class: className, ...props }: PanelSectionProps): VNode {\n  return <div {...props} class={cn('ns-panel__body', className)}>{children}</div>;\n}\n\nexport function PanelFooter({ children, class: className, ...props }: PanelSectionProps): VNode {\n  return <div {...props} class={cn('ns-panel__footer', className)}>{children}</div>;\n}\n\ntype PanelNamespace =\n  & typeof PanelRoot\n  & Readonly<{\n    Header: typeof PanelHeader;\n    Title: typeof PanelTitle;\n    Description: typeof PanelDescription;\n    Body: typeof PanelBody;\n    Footer: typeof PanelFooter;\n  }>;\n\nexport const Panel: PanelNamespace = Object.assign(PanelRoot, {\n  Header: PanelHeader,\n  Title: PanelTitle,\n  Description: PanelDescription,\n  Body: PanelBody,\n  Footer: PanelFooter,\n});\n";
const template_069 =
  '.ns-progress {\n  width: 100%;\n}\n\n.ns-progress__track {\n  position: relative;\n  display: block;\n  width: 100%;\n  overflow: hidden;\n  border-radius: var(--ns-radius-full);\n  background: color-mix(in srgb, var(--ns-border-hover) 90%, transparent);\n}\n\n.ns-progress--sm .ns-progress__track {\n  height: 0.325rem;\n}\n\n.ns-progress--md .ns-progress__track {\n  height: 0.5rem;\n}\n\n.ns-progress--lg .ns-progress__track {\n  height: 0.7rem;\n}\n\n.ns-progress__bar {\n  display: block;\n  height: 100%;\n  border-radius: inherit;\n  background: var(--ns-primary);\n  transition: width var(--ns-ease-normal);\n}\n\n.ns-progress--secondary .ns-progress__bar {\n  background: var(--ns-secondary);\n}\n\n.ns-progress--success .ns-progress__bar {\n  background: var(--ns-success);\n}\n\n.ns-progress--warning .ns-progress__bar {\n  background: var(--ns-warning);\n}\n\n.ns-progress--destructive .ns-progress__bar {\n  background: var(--ns-destructive);\n}\n\n.ns-progress--indeterminate .ns-progress__bar {\n  width: 42%;\n  animation: ns-progress-indeterminate 1.2s ease-in-out infinite;\n}\n\n@keyframes ns-progress-indeterminate {\n  0% {\n    transform: translateX(-120%);\n  }\n\n  50% {\n    transform: translateX(30%);\n  }\n\n  100% {\n    transform: translateX(180%);\n  }\n}\n\n/* Reduced motion: indeterminate sweep becomes a static partial fill. */\n@media (prefers-reduced-motion: reduce) {\n  .ns-progress--indeterminate .ns-progress__bar {\n    animation: none;\n    width: 42%;\n    transform: translateX(70%);\n  }\n}\n';
const template_070 =
  "/**\n * @component Progress\n * @layer 2\n * @depends theme-seed\n * @description Determinate or indeterminate progress indicator for jobs, uploads, and deferred flows.\n */\n\nimport type { JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\n\nexport type ProgressVariant = 'primary' | 'secondary' | 'success' | 'warning' | 'destructive';\nexport type ProgressSize = 'sm' | 'md' | 'lg';\n\nexport interface ProgressProps\n  extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'class' | 'children'> {\n  class?: string;\n  indeterminate?: boolean;\n  label?: string;\n  max?: number;\n  size?: ProgressSize;\n  value?: number;\n  variant?: ProgressVariant;\n}\n\nconst SIZE_CLASSES: Record<ProgressSize, string> = {\n  sm: 'ns-progress--sm',\n  md: 'ns-progress--md',\n  lg: 'ns-progress--lg',\n};\n\nconst VARIANT_CLASSES: Record<ProgressVariant, string | undefined> = {\n  primary: undefined,\n  secondary: 'ns-progress--secondary',\n  success: 'ns-progress--success',\n  warning: 'ns-progress--warning',\n  destructive: 'ns-progress--destructive',\n};\n\nfunction clamp(value: number, min: number, max: number): number {\n  return Math.min(Math.max(value, min), max);\n}\n\nexport function Progress({\n  class: className,\n  indeterminate = false,\n  label = 'Progress',\n  max = 100,\n  size = 'md',\n  value = 0,\n  variant = 'primary',\n  ...props\n}: ProgressProps): VNode {\n  const safeMax = max > 0 ? max : 100;\n  const normalizedValue = clamp(value, 0, safeMax);\n  const width = `${(normalizedValue / safeMax) * 100}%`;\n\n  return (\n    <div\n      {...props}\n      role='progressbar'\n      aria-label={label}\n      aria-valuemin={0}\n      aria-valuemax={safeMax}\n      aria-valuenow={indeterminate ? undefined : normalizedValue}\n      class={cn(\n        'ns-progress',\n        SIZE_CLASSES[size],\n        VARIANT_CLASSES[variant],\n        indeterminate && 'ns-progress--indeterminate',\n        className,\n      )}\n    >\n      <span class='ns-progress__track'>\n        <span class='ns-progress__bar' style={indeterminate ? undefined : { width }} />\n      </span>\n    </div>\n  );\n}\n";
const template_071 =
  ".ns-prompt-input {\n  display: flex;\n  flex-direction: column;\n  gap: var(--ns-space-2);\n  padding: var(--ns-space-3);\n  border: 1px solid var(--ns-input-border);\n  border-radius: var(--ns-radius-2xl);\n  background: var(--ns-card);\n  box-shadow: var(--ns-shadow-sm);\n  transition: border-color var(--ns-ease-normal), box-shadow var(--ns-ease-normal);\n}\n\n.ns-prompt-input:focus-within {\n  border-color: var(--ns-primary-border);\n  box-shadow: 0 0 0 3px var(--ns-primary-subtle);\n}\n\n.ns-prompt-input[data-compact] {\n  padding: var(--ns-space-2);\n}\n\n.ns-prompt-input__field {\n  width: 100%;\n  max-height: 12rem;\n  min-height: var(--ns-control-h);\n  field-sizing: content;\n  resize: none;\n  border: 0;\n  background: transparent;\n  color: var(--ns-fg);\n  font-family: inherit;\n  font-size: var(--ns-text-chat);\n  line-height: var(--ns-leading-normal);\n}\n\n.ns-prompt-input__field::placeholder {\n  color: var(--ns-muted-fg);\n}\n\n.ns-prompt-input__field:focus {\n  outline: none;\n}\n\n.ns-prompt-input__bar {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--ns-space-2);\n}\n\n/* Two coherent groups: wrapping never strands a lone control on its own row. */\n.ns-prompt-input__tools {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--ns-space-1-5);\n  min-width: 0;\n}\n\n.ns-prompt-input__actions {\n  display: flex;\n  align-items: center;\n  gap: var(--ns-space-1);\n  margin-inline-start: auto;\n}\n\n.ns-iconbtn svg,\n.ns-prompt-input__send svg {\n  display: block;\n}\n\n.ns-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ns-space-1);\n  height: var(--ns-control-h-sm);\n  padding-inline: var(--ns-space-2-5);\n  border: 1px solid var(--ns-border);\n  border-radius: var(--ns-radius-full);\n  background: transparent;\n  color: var(--ns-muted-fg);\n  font-size: var(--ns-text-2xs);\n  cursor: pointer;\n  transition:\n    color var(--ns-ease-fast),\n    border-color var(--ns-ease-fast),\n    background-color var(--ns-ease-fast);\n}\n\n.ns-pill:hover {\n  color: var(--ns-fg);\n  border-color: var(--ns-border-hover);\n}\n\n.ns-pill[aria-pressed='true'] {\n  color: var(--ns-primary);\n  border-color: var(--ns-primary-border);\n  background: var(--ns-primary-subtle);\n}\n\n.ns-pill:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: var(--ns-space-px);\n}\n\n.ns-iconbtn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: var(--ns-control-h-sm);\n  height: var(--ns-control-h-sm);\n  border: 0;\n  border-radius: var(--ns-radius-md);\n  background: transparent;\n  color: var(--ns-muted-fg);\n  font-family: var(--ns-font-mono);\n  font-size: var(--ns-text-sm);\n  cursor: pointer;\n  transition: color var(--ns-ease-fast), background-color var(--ns-ease-fast);\n}\n\n.ns-iconbtn:hover {\n  color: var(--ns-fg);\n  background: var(--ns-muted);\n}\n\n.ns-iconbtn:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: -2px;\n}\n\n.ns-prompt-input__send {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: var(--ns-control-h-sm);\n  height: var(--ns-control-h-sm);\n  border: 0;\n  border-radius: var(--ns-radius-full);\n  background: var(--ns-primary);\n  color: var(--ns-primary-fg);\n  font-size: var(--ns-text-sm);\n  cursor: pointer;\n  transition: background-color var(--ns-ease-fast);\n}\n\n.ns-prompt-input__send:hover {\n  background: var(--ns-primary-hover);\n}\n\n.ns-iconbtn:disabled,\n.ns-prompt-input__send:disabled {\n  cursor: not-allowed;\n  opacity: 0.5;\n}\n\n.ns-prompt-input__send:focus-visible {\n  outline: 2px solid var(--ns-ring);\n  outline-offset: 2px;\n}\n\n.ns-prompt-input__hint {\n  font-size: var(--ns-text-2xs);\n  color: var(--ns-muted-fg);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ns-prompt-input,\n  .ns-pill,\n  .ns-iconbtn,\n  .ns-prompt-input__send {\n    transition: none;\n  }\n}\n";
const template_072 =
  "/**\n * @component PromptInput\n * @layer 2\n * @depends theme-seed\n * @description Chat composer: an auto-grow textarea over a toolbar of toggle\n * pills (deep research / grounding), a ModelSelector, attach/screenshot/voice\n * affordances, and a send button. Presentational <form> — onSubmit reads the\n * field; textarea auto-grow is CSS-native and Enter-to-send is an app-island\n * enhancement.\n */\n\nimport type { ComponentChildren, JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\nimport { type ModelOption, ModelSelector } from './model-selector.tsx';\n\n/**\n * Submit metadata passed alongside the prompt text.\n */\nexport interface PromptSubmitMeta {\n  grounding: boolean;\n  research: boolean;\n  model: string;\n}\n\n/** Keyboard policies supported by PromptInput submission. */\nexport const PROMPT_SUBMIT_KEYS = ['none', 'enter', 'mod-enter'] as const;\n\n/** Keyboard policy used to submit the prompt textarea. */\nexport type PromptSubmitKey = typeof PROMPT_SUBMIT_KEYS[number];\n\n/** Minimal keyboard state used to evaluate a PromptInput submit policy. */\nexport interface PromptSubmitKeyEvent {\n  readonly key: string;\n  readonly ctrlKey: boolean;\n  readonly metaKey: boolean;\n  readonly shiftKey: boolean;\n  readonly isComposing: boolean;\n  readonly keyCode: number;\n}\n\n/** Returns whether a keyboard event should submit under the configured policy. */\nexport function shouldSubmitPromptKey(\n  event: PromptSubmitKeyEvent,\n  policy: PromptSubmitKey,\n): boolean {\n  if (event.isComposing || event.keyCode === 229) return false;\n  return policy === 'enter'\n    ? event.key === 'Enter' && !event.shiftKey\n    : policy === 'mod-enter'\n    ? event.key === 'Enter' && (event.ctrlKey || event.metaKey)\n    : false;\n}\n\nconst ICON_ATTACH = 'M12 5v14 M5 12h14';\nconst ICON_SCREENSHOT =\n  'M4 9V6a2 2 0 0 1 2-2h3 M15 4h3a2 2 0 0 1 2 2v3 M20 15v3a2 2 0 0 1-2 2h-3 M9 20H6a2 2 0 0 1-2-2v-3';\nconst ICON_MIC =\n  'M12 2a3 3 0 0 1 3 3v6a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3Z M5 11a7 7 0 0 0 14 0 M12 18v3';\nconst ICON_SEND = 'M12 19V5 M5 12l7-7 7 7';\nconst ICON_STOP = 'M7 7h10v10H7z';\n\nfunction IconGlyph({ d }: { d: string }): VNode {\n  return (\n    <svg\n      viewBox='0 0 24 24'\n      width='16'\n      height='16'\n      fill='none'\n      stroke='currentColor'\n      stroke-width='2'\n      stroke-linecap='round'\n      stroke-linejoin='round'\n      aria-hidden='true'\n    >\n      <path d={d} />\n    </svg>\n  );\n}\n\nexport interface PromptInputProps\n  extends Omit<JSX.HTMLAttributes<HTMLFormElement>, 'class' | 'onSubmit'> {\n  placeholder?: string;\n  onSubmit?: (text: string, meta: PromptSubmitMeta) => void;\n  models?: ModelOption[];\n  model?: string;\n  onModelChange?: (id: string) => void;\n  grounding?: boolean;\n  onGroundingChange?: (next: boolean) => void;\n  research?: boolean;\n  onResearchChange?: (next: boolean) => void;\n  hint?: string;\n  compact?: boolean;\n  class?: string;\n  onAttach?: () => void;\n  onScreenshot?: () => void;\n  onVoice?: () => void;\n  leadingActions?: ComponentChildren;\n  trailingActions?: ComponentChildren;\n  busy?: boolean;\n  onStop?: () => void;\n  sendDisabled?: boolean;\n  submitKey?: PromptSubmitKey;\n}\n\n/**\n * Renders the chat composer shell. Action affordances are capability-gated; after re-adding this\n * vendored registry component, supply callbacks or slots for every action that should appear.\n */\nexport function PromptInput(\n  {\n    placeholder = 'Ask anything…',\n    onSubmit,\n    models,\n    model = '',\n    onModelChange,\n    grounding = false,\n    onGroundingChange,\n    research = false,\n    onResearchChange,\n    hint,\n    compact,\n    onAttach,\n    onScreenshot,\n    onVoice,\n    leadingActions,\n    trailingActions,\n    busy = false,\n    onStop,\n    sendDisabled = false,\n    submitKey = 'none',\n    class: className,\n    ...props\n  }: PromptInputProps,\n): VNode {\n  function handleSubmit(event: JSX.TargetedEvent<HTMLFormElement, Event>) {\n    event.preventDefault();\n    const field = event.currentTarget.elements.namedItem('prompt') as HTMLTextAreaElement | null;\n    const text = field?.value.trim() ?? '';\n    if (!busy && !sendDisabled && text) onSubmit?.(text, { grounding, research, model });\n  }\n\n  function handleKeyDown(event: JSX.TargetedKeyboardEvent<HTMLTextAreaElement>): void {\n    if (busy || sendDisabled || !shouldSubmitPromptKey(event, submitKey)) return;\n    event.preventDefault();\n    event.currentTarget.form?.requestSubmit();\n  }\n\n  return (\n    <form\n      {...props}\n      class={cn('ns-prompt-input', className)}\n      data-compact={compact ? '' : undefined}\n      onSubmit={handleSubmit}\n    >\n      <textarea\n        name='prompt'\n        rows={1}\n        class='ns-prompt-input__field'\n        placeholder={placeholder}\n        aria-keyshortcuts={submitKey === 'enter'\n          ? 'Enter'\n          : submitKey === 'mod-enter'\n          ? 'Control+Enter Meta+Enter'\n          : undefined}\n        disabled={busy}\n        onKeyDown={handleKeyDown}\n      />\n      <div class='ns-prompt-input__bar'>\n        <div class='ns-prompt-input__tools'>\n          {leadingActions}\n          {onAttach\n            ? (\n              <button type='button' class='ns-iconbtn' aria-label='Attach file' onClick={onAttach}>\n                <IconGlyph d={ICON_ATTACH} />\n              </button>\n            )\n            : null}\n          {onResearchChange\n            ? (\n              <button\n                type='button'\n                class='ns-pill'\n                aria-pressed={research ? 'true' : 'false'}\n                onClick={() => onResearchChange?.(!research)}\n              >\n                Deep research\n              </button>\n            )\n            : null}\n          {onGroundingChange\n            ? (\n              <button\n                type='button'\n                class='ns-pill'\n                aria-pressed={grounding ? 'true' : 'false'}\n                onClick={() => onGroundingChange?.(!grounding)}\n              >\n                Grounding\n              </button>\n            )\n            : null}\n          {models && models.length\n            ? <ModelSelector value={model} models={models} onChange={onModelChange} align='left' />\n            : null}\n        </div>\n        <div class='ns-prompt-input__actions'>\n          {onScreenshot\n            ? (\n              <button\n                type='button'\n                class='ns-iconbtn'\n                aria-label='Capture screenshot'\n                onClick={onScreenshot}\n              >\n                <IconGlyph d={ICON_SCREENSHOT} />\n              </button>\n            )\n            : null}\n          {onVoice\n            ? (\n              <button type='button' class='ns-iconbtn' aria-label='Voice input' onClick={onVoice}>\n                <IconGlyph d={ICON_MIC} />\n              </button>\n            )\n            : null}\n          {trailingActions}\n          {busy && onStop\n            ? (\n              <button\n                type='button'\n                class='ns-prompt-input__send'\n                aria-label='Stop generating'\n                onClick={onStop}\n              >\n                <IconGlyph d={ICON_STOP} />\n              </button>\n            )\n            : (\n              <button\n                type='submit'\n                class='ns-prompt-input__send'\n                aria-label='Send'\n                disabled={busy || sendDisabled}\n              >\n                <IconGlyph d={ICON_SEND} />\n              </button>\n            )}\n        </div>\n      </div>\n      {hint ? <div class='ns-prompt-input__hint'>{hint}</div> : null}\n    </form>\n  );\n}\n";
