  "/**\n * @component Skeleton\n * @layer 2\n * @depends theme-seed\n * @description Generic dashboard loading scaffold for table, stats, detail, and form surfaces.\n */\n\nimport type { JSX, VNode } from 'preact';\nimport { cn } from '../../lib/cn.ts';\n\ninterface SkeletonProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'class' | 'children'> {\n  cards?: number;\n  class?: string;\n  columns?: number;\n  rows?: number;\n  variant: 'table' | 'stats' | 'detail' | 'form';\n}\n\nfunction clamp(value: number, fallback: number): number {\n  return Number.isFinite(value) && value > 0 ? Math.floor(value) : fallback;\n}\n\nfunction SkeletonBlock(\n  { class: className, style }: { class?: string; style?: JSX.CSSProperties },\n): VNode {\n  return <span aria-hidden='true' class={cn('ns-skeleton__block', className)} style={style} />;\n}\n\n/**\n * Renders loading scaffolds for table, stats, detail, and form states.\n */\nexport function Skeleton(\n  { cards = 4, class: className, columns = 4, rows = 4, variant, ...props }: SkeletonProps,\n): VNode {\n  const resolvedCards = clamp(cards, 4);\n  const resolvedColumns = clamp(columns, 4);\n  const resolvedRows = clamp(rows, 4);\n\n  if (variant === 'stats') {\n    return (\n      <div\n        {...props}\n        aria-hidden='true'\n        class={cn('ns-skeleton ns-skeleton--stats ns-grid', className)}\n      >\n        {Array.from(\n          { length: resolvedCards },\n          (_, index) => (\n            <div key={`stats-${index}`} class='ns-skeleton__card'>\n              <SkeletonBlock\n                class='ns-skeleton__line--xs'\n                style={{ width: `${38 + ((index % 3) * 8)}%` }}\n              />\n              <SkeletonBlock\n                class='ns-skeleton__line--lg'\n                style={{ width: `${58 + ((index % 2) * 14)}%` }}\n              />\n              <SkeletonBlock class='ns-skeleton__line--xs' style={{ width: '30%' }} />\n            </div>\n          ),\n        )}\n      </div>\n    );\n  }\n\n  if (variant === 'detail') {\n    return (\n      <div\n        {...props}\n        aria-hidden='true'\n        class={cn('ns-skeleton ns-skeleton--detail ns-stack ns-stack--lg', className)}\n      >\n        {Array.from(\n          { length: resolvedRows },\n          (_, index) => (\n            <div key={`detail-${index}`} class='ns-stack ns-stack--sm'>\n              <SkeletonBlock\n                class='ns-skeleton__line--md'\n                style={{ width: index === 0 ? '32%' : '24%' }}\n              />\n              <SkeletonBlock class='ns-skeleton__line--sm' style={{ width: '100%' }} />\n              <SkeletonBlock class='ns-skeleton__line--sm' style={{ width: '86%' }} />\n              <SkeletonBlock class='ns-skeleton__line--sm' style={{ width: '64%' }} />\n            </div>\n          ),\n        )}\n      </div>\n    );\n  }\n\n  if (variant === 'form') {\n    return (\n      <div\n        {...props}\n        aria-hidden='true'\n        class={cn('ns-skeleton ns-skeleton--form ns-stack ns-stack--md', className)}\n      >\n        {Array.from(\n          { length: resolvedRows },\n          (_, index) => (\n            <div key={`form-${index}`} class='ns-stack ns-stack--sm'>\n              <SkeletonBlock\n                class='ns-skeleton__line--xs'\n                style={{ width: `${30 + ((index % 3) * 12)}%` }}\n              />\n              <SkeletonBlock class='ns-skeleton__box ns-skeleton__box--input' />\n            </div>\n          ),\n        )}\n        <div class='ns-cluster'>\n          <SkeletonBlock\n            class='ns-skeleton__box ns-skeleton__box--input'\n            style={{ width: '7rem' }}\n          />\n          <SkeletonBlock\n            class='ns-skeleton__box ns-skeleton__box--input'\n            style={{ width: '5.5rem' }}\n          />\n        </div>\n      </div>\n    );\n  }\n\n  const tableColumns = `repeat(${resolvedColumns}, minmax(0, 1fr))`;\n\n  return (\n    <div\n      {...props}\n      aria-hidden='true'\n      class={cn('ns-skeleton ns-skeleton--table', className)}\n    >\n      <div\n        class='ns-skeleton__table-row ns-skeleton__table-row--head'\n        style={{ gridTemplateColumns: tableColumns }}\n      >\n        {Array.from(\n          { length: resolvedColumns },\n          (_, index) => (\n            <SkeletonBlock\n              key={`table-head-${index}`}\n              class='ns-skeleton__line--xs'\n              style={{ width: `${44 + ((index % 3) * 12)}%` }}\n            />\n          ),\n        )}\n      </div>\n      {Array.from({ length: resolvedRows }, (_, rowIndex) => (\n        <div\n          key={`table-row-${rowIndex}`}\n          class='ns-skeleton__table-row'\n          style={{ gridTemplateColumns: tableColumns }}\n        >\n          {Array.from({ length: resolvedColumns }, (_, columnIndex) => (\n            <SkeletonBlock\n              key={`table-cell-${rowIndex}-${columnIndex}`}\n              class='ns-skeleton__line--sm'\n              style={{ width: `${58 + (((rowIndex * 2 + columnIndex) % 4) * 9)}%` }}\n            />\n          ))}\n        </div>\n      ))}\n    </div>\n  );\n}\n";
const template_086 =
  '/* currentColor-driven so the arc adapts to its context (buttons set color).\n   Standalone default is the primary accent. */\n.ns-spinner {\n  display: inline-block;\n  color: var(--ns-primary);\n  border: 2px solid color-mix(in srgb, currentColor 22%, transparent);\n  border-top-color: currentColor;\n  border-right-color: currentColor;\n  border-radius: var(--ns-radius-full);\n  animation: ns-spin 0.7s linear infinite;\n}\n\n.ns-spinner--sm {\n  width: 16px;\n  height: 16px;\n}\n\n.ns-spinner--md {\n  width: 24px;\n  height: 24px;\n}\n\n.ns-spinner--lg {\n  width: 40px;\n  height: 40px;\n  border-width: 3px;\n}\n\n@keyframes ns-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n/* Reduced motion: spinner is an essential progress indicator, so it keeps\n   spinning, only slower. */\n@media (prefers-reduced-motion: reduce) {\n  .ns-spinner {\n    animation-duration: 1.5s;\n  }\n}\n';
