const template_088 =
  '/* StatsGrid block styles. Container-adaptive: the column count derives from\n   available width (auto-fit), not viewport breakpoints, so the grid behaves\n   in narrow rails, split panes, and embedded canvases alike. */\n\n.ns-stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(13rem, 100%), 1fr));\n  gap: var(--ns-space-4);\n}\n\n.ns-stats-grid__card {\n  overflow: hidden;\n}\n\n.ns-stats-grid__body {\n  min-width: 0;\n}\n\n.ns-stats-grid__header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--ns-space-3);\n}\n\n.ns-stats-grid__label {\n  font-family: var(--ns-font-mono);\n  font-size: var(--ns-text-2xs);\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  color: var(--ns-muted-fg);\n}\n\n.ns-stats-grid__value {\n  font-size: var(--ns-text-3xl);\n  font-weight: 600;\n  letter-spacing: var(--ns-tracking-tight);\n  font-variant-numeric: tabular-nums;\n  color: var(--ns-fg);\n}\n\n.ns-stats-grid__detail {\n  font-size: var(--ns-text-sm);\n  line-height: var(--ns-leading-relaxed);\n  color: var(--ns-muted-fg);\n}\n';
